<template>
  <component :is="management ? 'div' : ConsumerShell" class="issues-page">
    <ConsumerPageHeader  :title="management ? '投诉处理' : '我的投诉'" description="查看处理进度、提交补充说明或回复。"><router-link class="btn" :to="management?(route.path.startsWith('/government')?'/organization-review/government':'/org-desk/home'):'/portal/registration'">返回工作台</router-link></ConsumerPageHeader>
    <ConsumerState v-if="loading" loading title="正在读取问题处理进度"/><ConsumerState v-else-if="error" error title="问题记录暂时无法读取" :description="error"><button class="btn" @click="load">重新读取</button></ConsumerState>
    <section v-else-if="detail" class="consumer-card issue-detail"><div class="between"><div><span class="issue-number">问题编号 {{ detail.complaint.id }}</span><h2>{{ subject(detail.complaint.request) }}</h2></div><span class="issue-status">{{ labels[detail.complaint.status] }}</span></div><p class="consumer-muted">{{ detail.complaint.owner_id ? '责任岗位已接单，处理记录如下' : '等待主办方受理并指定办理人' }}</p><ol class="issue-timeline"><li v-for="(item,index) in detail.messages" :key="index"><span class="timeline-dot"/><div><p><strong>{{ actorLabels[item.actor_type]||'业务责任人' }} · {{ actionLabels[item.action]||'回复' }}</strong><small>{{ businessTime(item.occurred_at) }}</small></p><p>{{ item.message }}</p></div></li></ol><el-input v-model="reply" type="textarea" :rows="3" maxlength="2000" show-word-limit placeholder="补充具体情况或回复处理意见"/><div class="issue-actions"><el-button type="primary" :loading="busy" :disabled="!reply.trim()" @click="send('complaint.reply')">提交回复</el-button><el-button v-if="!management&&['resolved','rejected'].includes(detail.complaint.status)" :disabled="!reply.trim()||busy" @click="send('complaint.reopen')">申请重新处理</el-button><template v-if="management"><el-button v-for="action in ['accept','coordinate','resolve','reject']" :key="action" :disabled="!reply.trim()||busy" @click="send('complaint.handle',action)">{{ actionLabels[action] }}</el-button></template></div></section>
    <template v-else>
      <section v-if="!management" class="consumer-card issue-create"><h3>把需要解决的事说清楚</h3><el-form label-position="top"><el-form-item label="与哪场赛事或报名有关"><el-select v-model="selected" filterable placeholder="选择相关赛事或我的报名" style="width:100%"><el-option v-for="item in targets" :key="item.key" :value="item.key" :label="item.label"/></el-select></el-form-item><el-form-item label="遇到了什么，希望怎样解决"><el-input v-model="message" type="textarea" :rows="4" maxlength="2000" show-word-limit placeholder="例如：比赛改期后无法参加，希望主办方核对退款安排。请不要填写证件号码或支付密码。"/></el-form-item><el-button type="primary" :loading="busy" :disabled="!selected||!message.trim()" @click="submit">提交并获取问题编号</el-button></el-form></section>
      <div class="section-head"><h2>{{ management?'待办理与历史问题':'我的问题记录' }}</h2><span class="small">{{ rows.length }} 条</span></div><ConsumerState v-if="!rows.length" title="目前没有待处理的问题" description="若遇到参赛或退款问题，可以在这里提交并持续跟进。"/><div class="issue-list"><router-link v-for="row in rows" :key="row.id" :to="(management?managementBase:'/portal/issues')+'/'+row.id"><div><strong>{{ subject(row.request) }}</strong><p>{{ row.organization_name }} · {{ businessTime(row.create_time) }}</p><small>编号 {{ row.id }}</small></div><span class="issue-status">{{ labels[row.status] }}</span><span>→</span></router-link></div>
    </template>
  </component>
</template>
<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import request from '@/utils/request';import {businessTime} from '@/utils/business';import {performAction} from '@/api/sports/phase1';import ConsumerShell from '@/layout/consumer/ConsumerShell.vue';import ConsumerPageHeader from '@/components/consumer/ConsumerPageHeader.vue';import ConsumerState from '@/components/consumer/ConsumerState.vue';
interface Issue {id:string;object_type:string;object_id:string;status:string;owner_id:string|null;version:number;request:unknown;create_time:string;organization_name:string;}
const route=useRoute(),router=useRouter(),management=computed(()=>!route.path.startsWith('/portal/')),managementBase=computed(()=>route.path.startsWith('/government/')?'/government/issues':'/org-desk/issues'),id=computed(()=>String(route.params.id||''));
const rows=ref<Issue[]>([]),detail=ref<{complaint:Issue;messages:{actor_type:string;action:string;message:string;occurred_at:string}[]}>(),loading=ref(false),busy=ref(false),error=ref(''),message=ref(''),reply=ref(''),selected=ref(''),targets=ref<{key:string;label:string;type:string;id:string}[]>([]);
const labels:Record<string,string>={submitted:'等待受理',accepted:'已受理',investigating:'正在协调',resolved:'已解决',rejected:'已说明处理结论',appealed:'已申请重新处理'};
const actionLabels:Record<string,string>={submitted:'提交问题',reply:'回复',reopen:'重新申请处理',accept:'受理并接单',coordinate:'进入协调',resolve:'确认解决',reject:'给出无法受理的依据'};
const actorLabels:Record<string,string>={platform:'反馈人',organizer:'主办方',government:'政府协调岗位',admin:'平台管理岗位'};
const subject=(value:unknown)=>{try{const obj=typeof value==='string'?JSON.parse(value):value as {message?:string;value?:string};if(obj?.value)return JSON.parse(obj.value).message;return obj?.message||'赛事问题';}catch{return '赛事问题';}};
const load=async()=>{loading.value=true;error.value='';try{if(id.value)detail.value=(await request({url:'/sports/issues/'+id.value})).data;else{detail.value=undefined;rows.value=(await request({url:'/sports/issues'})).data;if(!management.value){const results=await Promise.allSettled([request({url:'/sports/public/events',headers:{isToken:false}}),request({url:'/sports/c/registrations'})]);targets.value=[];for(let index=0;index<results.length;index++){const res=results[index];if(res.status==='fulfilled')for(const row of res.value.data){const type=index===0?'event':'registration';targets.value.push({key:type+':'+row.id,id:row.id,type,label:index===0?'赛事 · '+row.name:'我的报名 · '+row.unitName});}}if(route.query.eventId)selected.value='event:'+route.query.eventId;}}}catch(e){error.value=e instanceof Error?e.message:'请稍后重试';}finally{loading.value=false;}};
const submit=async()=>{const target=targets.value.find(t=>t.key===selected.value);if(!target||busy.value)return;busy.value=true;try{const res=await performAction('complaint.submit',{objectType:target.type,objectId:target.id,message:message.value},'向相关主办方提交这项问题，内容仅向你和必要的处理岗位展示。');message.value='';ElMessage.success('已收到，请保留问题编号并关注回复');await router.push('/portal/issues/'+res.data.result.complaintId);}finally{busy.value=false;}};
const send=async(code:string,action?:string)=>{if(!detail.value||busy.value)return;busy.value=true;try{await performAction(code,{complaintId:id.value,message:reply.value,expectedVersion:detail.value.complaint.version,...(action?{action}:{})},code==='complaint.reply'?undefined:'请核对本次处理意见。确认后将记录责任岗位、内容和时间，并通知相关当事人。');reply.value='';await load();}finally{busy.value=false;}};
onMounted(load);watch(()=>route.fullPath,load);
</script>
<style scoped>.issues-page{padding:24px}.issue-create{max-width:800px;margin:24px auto}.issue-create h3{margin-bottom:24px}.issue-list{display:flex;flex-direction:column;gap:14px}.issue-list>a{background:white;border:1px solid #e3eade;border-radius:16px;padding:22px;display:flex;gap:20px;align-items:center;color:#39543d}.issue-list>a>div{flex:1;min-width:0}.issue-list strong,.issue-detail h2{overflow-wrap:anywhere}.issue-list p,.issue-list small{color:#91a082;font-size:12px}.issue-status{background:#eef4e8;color:#658154;font-size:12px;border-radius:20px;padding:6px 12px;white-space:nowrap}.issue-number{font-size:12px;color:#97a48a}.issue-detail{max-width:900px;margin:24px auto}.issue-detail h2{font-size:22px;margin-top:14px;line-height:1.6}.issue-timeline{list-style:none;padding:10px 0 20px}.issue-timeline li{display:flex;gap:18px;padding:18px 0;position:relative}.timeline-dot{margin-top:6px;width:10px;height:10px;border:2px solid #6c9f73;border-radius:50%;flex-shrink:0}.issue-timeline li>div{flex:1;min-width:0}.issue-timeline p:first-child{display:flex;justify-content:space-between;gap:12px;font-size:13px}.issue-timeline small{color:#a0a990;font-size:11px}.issue-timeline p:last-child{font-size:14px;line-height:1.8;color:#6d7a64;white-space:pre-wrap;overflow-wrap:anywhere}.issue-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}@media(max-width:640px){.issues-page{padding:0}.issue-timeline p:first-child,.issue-detail .between{flex-wrap:wrap}.issue-list>a{gap:10px;padding:18px}.issue-list small{overflow-wrap:anywhere;display:block}}</style>
